lib = '''"""Reusable helpers for Continual-ARC grid tasks."""

from collections import defaultdict


def comps(g, v):
    """4-connected components of cells with value v."""
    seen, out = set(), []
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] == v and (r, c) not in seen:
                st, cells = [(r, c)], []
                seen.add((r, c))
                while st:
                    a, b = st.pop()
                    cells.append((a, b))
                    for x, y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0 <= x < len(g) and 0 <= y < len(g[0]) and g[x][y] == v and (x, y) not in seen:
                            seen.add((x, y)); st.append((x, y))
                out.append(cells)
    return out


def objects(g):
    """Return (background, list of (color, cells)) for all non-bg objects."""
    from collections import Counter
    cnt = Counter(v for row in g for v in row)
    bg = cnt.most_common(1)[0][0]
    oo = []
    for v in cnt:
        if v != bg:
            for cells in comps(g, v):
                oo.append((v, cells))
    return bg, oo


def norm_shape(cells):
    """Translation-invariant shape signature (orientation fixed)."""
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    return tuple(sorted((r - r0, c - c0) for r, c in cells))


def is_L_object(cells):
    """True if cells form a proper L: a full column plus a full row of its bbox."""
    S = set(cells)
    rows = range(min(r for r, c in S), max(r for r, c in S) + 1)
    cols = range(min(c for r, c in S), max(c for r, c in S) + 1)
    if len(S) != len(rows) + len(cols) - 1:
        return False
    for R in rows:
        for C in cols:
            if S == {(r, C) for r in rows} | {(R, c) for c in cols}:
                return True
    return False


def l_absorption_transform(g):
    """Grid rule (task-b21f4de9): the unique big L-shaped object recolors the
    member lying OUTSIDE the L's bbox of the unique same-shape twin pair
    (exactly one twin member inside the L bbox)."""
    bg, oo = objects(g)
    L = max((cells for v, cells in oo if is_L_object(cells)), key=len)
    lv = g[L[0][0]][L[0][1]]
    bb = (min(r for r, c in L), max(r for r, c in L), min(c for r, c in L), max(c for r, c in L))
    groups = defaultdict(list)
    for v, cells in oo:
        if cells != L and len(cells) > 1:
            groups[norm_shape(cells)].append(cells)
    cands = []
    for mem in groups.values():
        if len(mem) == 2:
            inside = [m for m in mem if all(bb[0] <= r <= bb[1] and bb[2] <= c <= bb[3] for r, c in m)]
            if len(inside) == 1:
                cands.append([m for m in mem if m not in inside][0])
    assert len(cands) == 1, f"expected 1 twin pair, got {len(cands)}"
    tgt = set(cands[0])
    return [[lv if (r, c) in tgt else g[r][c] for c in range(len(g[0]))] for r in range(len(g))]
